const items = $input.all();
const results = [];

for (const item of items) {
  let parsed;
  try {
    const raw = (item.json.output || '')
      .replace(/```json/g, '')
      .replace(/```/g, '')
      .trim();
    parsed = JSON.parse(raw);
  } catch (e) {
    parsed = {
      verdict: 'unknown',
      confidence: 0,
      indicators: [],
      reasoning: 'Failed to parse: ' + (item.json.output || 'no output')
    };
  }

  // source 优先从解析出的 JSON 里取（agent prompt 里要求返回 source 字段）
  // 如果 agent 没返回 source，从上游 item 取
  if (!parsed.source) {
    parsed.source = item.json.source || 'unknown';
  }

  results.push({ json: parsed });
}

return results;

const items = $input.all();

const zeek = items.find(i => i.json.source === 'zeek')?.json || {};
const suricata = items.find(i => i.json.source === 'suricata')?.json || {};

// apply confidence threshold degradation rule
function applyThreshold(result) {
  if (!result.verdict) return result;

  // confidence < 0.75, malicious degraded to suspicious
  if (result.verdict === 'malicious' && result.confidence < 0.75) {
    return { ...result, verdict: 'suspicious', downgraded: true };
  }
  // confidence < 0.5, suspicious degraded to benign
  if (result.verdict === 'suspicious' && result.confidence < 0.5) {
    return { ...result, verdict: 'benign', downgraded: true };
  }
  return result;
}

const zeekAdjusted = applyThreshold(zeek);
const suricataAdjusted = applyThreshold(suricata);

// only if both outputs suspicious/malicious
// or one labelled malicious with confidence >= 0.85
const bothEscalate = (
  (zeekAdjusted.verdict === 'suspicious' || zeekAdjusted.verdict === 'malicious') &&
  (suricataAdjusted.verdict === 'suspicious' || suricataAdjusted.verdict === 'malicious')
);

const highConfidenceMalicious = (
  (zeekAdjusted.verdict === 'malicious' && zeekAdjusted.confidence >= 0.85) ||
  (suricataAdjusted.verdict === 'malicious' && suricataAdjusted.confidence >= 0.85)
);

// verdict：pick higher severity one with confidence constraints
function combineVerdict(z, s) {
  const order = { malicious: 3, suspicious: 2, benign: 1, unknown: 0 };
  const zScore = order[z.verdict] || 0;
  const sScore = order[s.verdict] || 0;

  if (zScore >= sScore) return z.verdict;
  return s.verdict;
}

return [{
  json: {
    zeek: zeekAdjusted,
    suricata: suricataAdjusted,
    combinedVerdict: combineVerdict(zeekAdjusted, suricataAdjusted),
    needsEscalation : (
      zeekAdjusted.verdict === 'suspicious' || zeekAdjusted.verdict === 'malicious' ||
      suricataAdjusted.verdict === 'suspicious' || suricataAdjusted.verdict === 'malicious'
    ),
  }
}];

const raw = $input.first().json.output
  .replace(/```json/g, '')
  .replace(/```/g, '')
  .trim();

let report;
try {
  report = JSON.parse(raw);
} catch(e) {
  return [{ json: { response: raw } }];
}

const text = `
🚨 INCIDENT REPORT — ${report.incident_id}
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
Severity : ${report.severity}
Verdict  : ${report.verdict}
Confidence: ${(report.confidence * 100).toFixed(0)}%

📋 Summary
${report.summary}

🔍 Indicators of Compromise
${(report.indicators_of_compromise || []).map(i => `• ${i}`).join('\n') || '• None identified'}

📅 Correlated Timeline
${(report.correlated_timeline || []).map(t => `• ${t}`).join('\n') || '• No timeline data'}

✅ Recommended Actions
${(report.recommended_actions || []).map(a => `• ${a}`).join('\n') || '• Continue monitoring'}

🧠 Justification
${report.justification}
`.trim();

// 自动保存
const fs = require('fs');
const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
const savePath = `/home/node/reports/incident_${timestamp}.txt`;
fs.mkdirSync('/home/node/reports', { recursive: true });
fs.writeFileSync(savePath, text, 'utf8');

const verdict = report.verdict || 'unknown';
const severity = report.severity || 'unknown';

return [{ json: { 
  response: text,
  savedPath: savePath,
  verdict: verdict,
  severity: severity,
  incidentId: report.incident_id || 'unknown'
}}];

const now = new Date();
const fiveMinAgo = new Date(now.getTime() - 5 * 60 * 1000);

return [{
  json: {
    from: fiveMinAgo.toISOString(),
    to: now.toISOString()
  }
}];

const zeekHits = $input.first().json.hits?.hits || [];

const zeekByType = {};
for (const h of zeekHits) {
  const s = h._source;
  const logType = s.container?.id || 'unknown';
  if (!zeekByType[logType]) zeekByType[logType] = [];

  let line = `ts=${s['@timestamp']}`;
  if (s.source?.ip)         line += ` src=${s.source.ip}:${s.source?.port || '?'}`;
  if (s.destination?.ip)    line += ` dst=${s.destination.ip}:${s.destination?.port || '?'}`;
  if (s.network?.transport) line += ` proto=${s.network.transport}`;
  if (s.network?.protocol)  line += ` service=${s.network.protocol}`;

  if (logType === 'conn.log') {
    if (s.event?.duration !== undefined) line += ` duration=${s.event.duration}`;
    if (s.network?.bytes !== undefined)  line += ` bytes=${s.network.bytes}`;
    if (s.source?.geo?.country_iso_code) line += ` src_country=${s.source.geo.country_iso_code}`;
  } else if (logType === 'dns.log') {
    const z = s.zeek?.dns || s.dns || {};
    if (z.query)      line += ` query="${z.query}"`;
    if (z.qtype_name) line += ` type=${z.qtype_name}`;
    if (z.rcode_name) line += ` rcode=${z.rcode_name}`;
  } else if (logType === 'http.log') {
    const z = s.zeek?.http || s.http || {};
    if (z.method)              line += ` method=${z.method}`;
    if (z.uri || s.url?.original) line += ` uri="${z.uri || s.url?.original}"`;
    if (z.status_code)         line += ` status=${z.status_code}`;
    if (z.user_agent)          line += ` ua="${z.user_agent}"`;
  } else if (logType === 'ssl.log') {
    const z = s.zeek?.ssl || s.tls || {};
    if (z.server_name || s.tls?.client?.server_name)
      line += ` sni="${z.server_name || s.tls?.client?.server_name}"`;
    if (z.validation_status) line += ` cert_valid=${z.validation_status}`;
  } else if (logType === 'notice.log') {
    const z = s.zeek?.notice || s.notice || {};
    if (z.note || z.note_type) line += ` note="${z.note || z.note_type}"`;
    if (z.message || z.msg)    line += ` msg="${z.message || z.msg}"`;
  } else if (logType === 'weird.log') {
    const z = s.zeek?.weird || s.weird || {};
    if (z.name) line += ` weird="${z.name}"`;
    if (z.addl) line += ` detail="${z.addl}"`;
  } else if (logType === 'kerberos.log') {
    const z = s.zeek?.kerberos || s.kerberos || {};
    if (z.request_type)          line += ` req_type=${z.request_type}`;
    if (z.client)                line += ` client="${z.client}"`;
    if (z.service)               line += ` service="${z.service}"`;
    if (z.success !== undefined) line += ` success=${z.success}`;
  } else if (logType === 'rdp.log') {
    const z = s.zeek?.rdp || s.rdp || {};
    if (z.cookie)                     line += ` cookie="${z.cookie}"`;
    if (z.auth_success !== undefined) line += ` auth=${z.auth_success}`;
  } else if (logType === 'smb_files.log') {
    const z = s.zeek?.smb_files || s.smb || {};
    if (z.action) line += ` action=${z.action}`;
    if (z.path)   line += ` path="${z.path}"`;
    if (z.name)   line += ` file="${z.name}"`;
  }

  zeekByType[logType].push(line);
}

const priorityOrder = [
  'notice.log','weird.log','conn.log','dns.log',
  'http.log','ssl.log','kerberos.log','rdp.log',
  'smb_files.log','dce_rpc.log'
];

let zeekText = 'No Zeek logs in this time window.';
if (zeekHits.length > 0) {
  const ordered = [
    ...priorityOrder.filter(t => zeekByType[t]),
    ...Object.keys(zeekByType).filter(t => !priorityOrder.includes(t))
  ];
  zeekText = ordered.map(logType => {
    return `=== ${logType.replace('.log','')} (${zeekByType[logType].length} events) ===\n`
      + zeekByType[logType].join('\n');
  }).join('\n\n');
}

return [{ json: { source: 'zeek', logs: zeekText } }];

const suricataHits = $input.first().json.hits?.hits || [];

const suricataText = suricataHits.length === 0
  ? 'No Suricata alerts in this time window.'
  : suricataHits.map(h => {
      const s = h._source;
      return [
        `ts=${s['@timestamp']}`,
        `src=${s.source?.ip}:${s.source?.port}`,
        `dst=${s.destination?.ip}:${s.destination?.port}`,
        `proto=${s.network?.transport}`,
        `severity=${s.rule?.severity}`,
        `signature="${s.rule?.name}"`,
        `category="${s.rule?.category}"`
      ].filter(Boolean).join(' ');
    }).join('\n');

return [{ json: { source: 'suricata', logs: suricataText } }];
